console.log('A');

setTimeout(() => console.log('timeout'), 0);

Promise.resolve()
  .then(() => {
    console.log('promise 1');
    Promise.resolve().then(() => console.log('promise 2'));
  });

console.log('B');

// A, B, promise 1, promise 2, timeout

async function demo() {
  console.log('start');
  await Promise.resolve();
  console.log('after await'); // microtask continuation
}

demo();
console.log('sync after call');

// start, sync after call, after await

Promise.resolve().then(() => console.log('promise'));
process.nextTick(() => console.log('nextTick'));

// nextTick, then promise

// Task continuations schedule on thread pool — not a single-thread microtask drain
await Task.Delay(1);
Console.WriteLine("continues on pool thread");
